+<?php
+
+namespace App\Entity;
+
+use App\Repository\FicheDocumentRepository;
+use Doctrine\ORM\Mapping as ORM;
+use Symfony\Component\HttpFoundation\File\File;
+use Vich\UploaderBundle\Mapping\Annotation as Vich;
+
+#[ORM\Entity(repositoryClass: FicheDocumentRepository::class)]
+class FicheDocument
+{
+    #[ORM\Id]
+    #[ORM\GeneratedValue]
+    #[ORM\Column]
+    private ?int $id = null;
+
+    #[ORM\Column(length: 255, nullable: true)]
+    private ?string $fileName = null;
+    /**
+     * @Vich\UploadableField(mapping="fiches_pdf", fileNameProperty="fileName")
+     */
+    private ?File $pdfFile = null;
+
+    public function getId(): ?int
+    {
+        return $this->id;
+    }
+
+    public function getFileName(): ?string
+    {
+        return $this->fileName;
+    }
+
+    public function setFileName(?string $fileName): self
+    {
+        $this->fileName = $fileName;
+
+        return $this;
+    }
+     
+      #[ORM\ManyToOne(targetEntity=Fiche::class, inversedBy="documents")]
+      #[ORM\JoinColumn(nullable=false)]
+     
+    private ?Fiche $fiche = null;
+}

